//! `elm-connect check`: a tree that is current, one with a module
//! missing, one differing, a stale file beside handwritten ones, one
//! generated by another release and one generated with other options,
//! in-process and through the binary for the exit status and the
//! command it prints.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use elm_connect::{Check, Drift};
use elm_connect_gen::{GeneratedFile, Options, SENTINEL, VERSION};

fn services_input() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../conformance/cases/services/input")
}

/// The services case's modules, `Notes/V1.elm` and
/// `Notes/V1/NotesService.elm`, as generating gives them.
fn generated() -> Vec<GeneratedFile> {
    generated_with(&Options::default())
}

/// The services case's modules as generating with `options` gives them.
fn generated_with(options: &Options) -> Vec<GeneratedFile> {
    elm_connect::generate(
        &[PathBuf::from("notes.proto")],
        &[services_input()],
        false,
        options,
    )
    .unwrap_or_else(|report| panic!("{report:?}"))
    .files
}

/// The options a plugin parameter sets.
fn options(parameter: &str) -> Options {
    Options::from_parameter(parameter).unwrap_or_else(|problems| panic!("{problems:?}"))
}

/// A fresh output directory named `name` holding the generated modules.
fn written(name: &str) -> (PathBuf, Vec<GeneratedFile>) {
    written_with(name, &Options::default())
}

/// A fresh output directory named `name` holding the modules generated
/// with `options`.
fn written_with(name: &str, options: &Options) -> (PathBuf, Vec<GeneratedFile>) {
    let out = Path::new(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&out);
    let files = generated_with(options);
    elm_connect::write(&files, &out).expect("write the output");
    (out, files)
}

/// What the report's regenerate command starts with in these tests.
const GEN: &str = "elm-connect gen notes.proto --out generated";

fn check_tree(files: &[GeneratedFile], out: &Path) -> Check {
    elm_connect::check(files, out).unwrap_or_else(|report| panic!("{report:?}"))
}

#[test]
fn a_tree_just_generated_is_current() {
    let (out, files) = written("check-current");
    let check = check_tree(&files, &out);
    assert!(check.is_current(), "{check:?}");
    assert!(check.other_options.is_empty());
    // The package's module, its service's, and one per message and enum.
    assert_eq!(check.modules, 14);
    assert!(
        check.render(GEN).contains("14 generated modules"),
        "{}",
        check.render(GEN)
    );
}

#[test]
fn a_missing_module_is_drift() {
    let (out, files) = written("check-missing");
    fs::remove_file(out.join("Notes/V1/NotesService.elm")).expect("remove");
    let check = check_tree(&files, &out);
    assert_eq!(
        check.drift,
        [Drift::Missing {
            path: "Notes/V1/NotesService.elm".into()
        }]
    );
    assert_eq!(check.version_only(), None);
    assert!(
        check.render(GEN).contains("missing: "),
        "{}",
        check.render(GEN)
    );

    let nothing = check_tree(&files, &out.join("absent"));
    assert_eq!(nothing.drift.len(), files.len());
}

#[test]
fn a_differing_module_is_drift_with_a_diff() {
    let (out, files) = written("check-differs");
    let path = out.join("Notes/V1.elm");
    let text = fs::read_to_string(&path).expect("read");
    fs::write(&path, text.replacen("-- TYPES", "-- TYPE", 1)).expect("write");
    let check = check_tree(&files, &out);
    let paths: Vec<&str> = check.drift.iter().map(Drift::path).collect();
    assert_eq!(paths, ["Notes/V1.elm"]);
    assert_eq!(check.version_only(), None);
    let report = check.render(GEN);
    assert!(report.contains("@@"), "{report}");
    let label = out.join("Notes/V1.elm");
    assert!(
        report.contains(&format!("--- {} (on disk)\n", label.display())),
        "{report}"
    );
    assert!(
        report.contains(&format!("+++ {} (generated)\n", label.display())),
        "{report}"
    );
    assert!(report.contains("\n--- TYPE\n"), "{report}");
    assert!(report.contains("+-- TYPES"), "{report}");
    assert!(report.contains("are out of date"), "{report}");
}

#[test]
fn a_stale_generated_file_is_drift_and_handwritten_ones_are_not() {
    let (out, files) = written("check-stale");
    let notes = fs::read_to_string(out.join("Notes/V1.elm")).expect("read");
    fs::create_dir_all(out.join("Old")).expect("create");
    fs::write(out.join("Old/V1.elm"), notes.replace("Notes.V1", "Old.V1")).expect("write");
    fs::write(out.join("Main.elm"), "module Main exposing (main)\n").expect("write");
    fs::write(
        out.join("Notes/Helpers.elm"),
        "-- Helpers for the generated notes client.\nmodule Notes.Helpers exposing (..)\n",
    )
    .expect("write");
    // Another invocation's module, from other protos, sharing the
    // directory.
    fs::create_dir_all(out.join("Users")).expect("create");
    fs::write(
        out.join("Users/V1.elm"),
        notes
            .replacen("from notes.proto.", "from users/v1/user.proto.", 1)
            .replace("Notes.V1", "Users.V1"),
    )
    .expect("write");
    let check = check_tree(&files, &out);
    assert_eq!(
        check.drift,
        [Drift::Stale {
            path: "Old/V1.elm".into()
        }]
    );
    assert!(
        check.render(GEN).contains("stale: "),
        "{}",
        check.render(GEN)
    );
    assert_eq!(
        elm_connect::stale(&files, &out).expect("stale"),
        ["Old/V1.elm"]
    );
}

/// `content` as another release would have generated it.
fn as_release(content: &str, version: &str, sentinel: &str) -> String {
    content
        .replacen(
            &format!("elm-connect {VERSION} "),
            &format!("elm-connect {version} "),
            1,
        )
        .replacen(
            &format!("Proto.Version.{SENTINEL}\n"),
            &format!("Proto.Version.{sentinel}\n"),
            1,
        )
}

#[test]
fn a_tree_from_another_release_says_so_once() {
    let (out, files) = written("check-version");
    for file in &files {
        let path = out.join(&file.path);
        let text = fs::read_to_string(&path).expect("read");
        fs::write(&path, as_release(&text, "0.0.7", "v0_0")).expect("write");
    }
    let check = check_tree(&files, &out);
    assert_eq!(check.drift.len(), files.len());
    assert_eq!(check.version_only(), Some(vec!["0.0.7".to_owned()]));
    let report = check.render(GEN);
    assert!(
        report.contains("generated by elm-connect 0.0.7"),
        "{report}"
    );
    assert!(
        report.contains(&format!("this is elm-connect {VERSION}")),
        "{report}"
    );
    assert!(!report.contains("@@"), "{report}");

    // Only the header line changed: still one message.
    let path = out.join("Notes/V1.elm");
    fs::write(&path, as_release(&files[0].content, "0.1.99", SENTINEL)).expect("write");
    assert_eq!(
        check_tree(&files, &out).version_only(),
        Some(vec!["0.0.7".to_owned(), "0.1.99".to_owned()])
    );

    // Any other change makes it ordinary drift.
    let text = fs::read_to_string(&path).expect("read");
    fs::write(&path, text.replacen("-- TYPES", "-- TYPE", 1)).expect("write");
    let again = check_tree(&files, &out);
    assert_eq!(again.version_only(), None);
    assert!(again.render(GEN).contains("@@"));
}

#[test]
fn a_tree_from_a_release_that_recorded_no_options_says_so_once() {
    let (out, files) = written("check-version-unrecorded");
    for file in &files {
        let path = out.join(&file.path);
        let text = fs::read_to_string(&path).expect("read");
        let mut lines: Vec<&str> = text.split_inclusive('\n').collect();
        assert!(lines[1].starts_with("-- Options: "), "{text}");
        lines.remove(1);
        fs::write(&path, as_release(&lines.concat(), "0.0.7", "v0_0")).expect("write");
    }
    let check = check_tree(&files, &out);
    assert!(check.other_options.is_empty(), "{check:?}");
    assert_eq!(check.version_only(), Some(vec!["0.0.7".to_owned()]));
}

#[test]
fn the_header_records_the_options() {
    let first_two = |files: &[GeneratedFile]| -> String {
        files[0]
            .content
            .lines()
            .take(2)
            .collect::<Vec<_>>()
            .join("\n")
    };
    let defaults = first_two(&generated());
    assert!(defaults.ends_with("\n-- Options: defaults"), "{defaults}");
    let given = first_two(&generated_with(&options(
        "module_prefix=Api,int64=int,rename=notes.v1.Note:Memo,enum_unknown=fail",
    )));
    assert!(
        given.ends_with("\n-- Options: int64=int, rename=notes.v1.Note:Memo, module_prefix=Api"),
        "{given}"
    );
}

#[test]
fn a_tree_generated_with_other_options_names_them() {
    let (out, _) = written("check-options");
    let files = generated_with(&options("int64=int,streaming=skip"));
    let check = check_tree(&files, &out);
    assert_eq!(check.version_only(), None);
    assert_eq!(check.other_options.len(), 1, "{check:?}");
    assert_eq!(check.other_options[0].on_disk, Vec::<String>::new());
    assert_eq!(
        check.other_options[0].generated,
        ["int64=int", "streaming=skip"]
    );
    let report = check.render(GEN);
    assert_eq!(
        report,
        format!(
            "The modules under {} were generated with other options than this check was \
             given:\n  \
             --int64: `string` (the default) on disk, `int` here\n  \
             --streaming: `error` (the default) on disk, `skip` here\n\
             To regenerate them with the options on disk, run:\n  {GEN}\n\
             To give them this check's options instead, run `elm-connect gen` with the same \
             arguments as this check, and delete any stale file.\n",
            out.display()
        )
    );
    assert!(!report.contains("@@"), "{report}");
}

#[test]
fn a_prefixed_tree_names_its_options_through_its_stale_modules() {
    let (out, _) = written_with(
        "check-options-prefix",
        &options("module_prefix=Api,rename=notes.v1.Note:Memo"),
    );
    let check = check_tree(&generated(), &out);
    // Every module moves: each is missing, and each prefixed one stale.
    assert!(
        check
            .drift
            .iter()
            .all(|drift| !matches!(drift, Drift::Differs { .. })),
        "{check:?}"
    );
    let report = check.render(GEN);
    assert!(
        report.contains("  --rename: `notes.v1.Note:Memo` on disk, none here\n"),
        "{report}"
    );
    assert!(
        report.contains("  --module-prefix: `Api` on disk, none here\n"),
        "{report}"
    );
    assert!(
        report.contains(&format!(
            "\n  {GEN} --rename notes.v1.Note:Memo --module-prefix Api\n"
        )),
        "{report}"
    );
}

/// `elm-connect check` on the services case into `out`, with `extra`
/// arguments.
fn run_check(out: &Path, extra: &[&str]) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .arg("check")
        .arg("notes.proto")
        .arg("-I")
        .arg(services_input())
        .arg("--out")
        .arg(out)
        .args(extra)
        .output()
        .expect("run elm-connect")
}

#[test]
fn the_exit_status_says_whether_the_tree_is_current() {
    let (out, _) = written("check-exit");
    let current = run_check(&out, &[]);
    assert_eq!(current.status.code(), Some(0), "{current:?}");

    let drifted = run_check(&out, &["--int64", "int"]);
    assert_eq!(drifted.status.code(), Some(1), "{drifted:?}");
    let stdout = String::from_utf8_lossy(&drifted.stdout);
    assert!(
        stdout.contains("generated with other options than this check was given"),
        "{stdout}"
    );
    assert!(
        stdout.contains(&format!(
            "  elm-connect gen -I {} notes.proto --out {}\n",
            services_input().display(),
            out.display()
        )),
        "{stdout}"
    );

    let notes = out.join("Notes/V1.elm");
    let text = fs::read_to_string(&notes).expect("read");
    fs::write(&notes, text.replacen("-- TYPES", "-- TYPE", 1)).expect("write");
    let edited = run_check(&out, &[]);
    assert_eq!(edited.status.code(), Some(1), "{edited:?}");
    let stdout = String::from_utf8_lossy(&edited.stdout);
    assert!(stdout.contains("are out of date"), "{stdout}");

    let failed = Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .args(["check", "missing.proto", "--out"])
        .arg(&out)
        .output()
        .expect("run elm-connect");
    assert_eq!(failed.status.code(), Some(2), "{failed:?}");
    assert!(failed.stdout.is_empty(), "{failed:?}");

    let unparsable = run_check(&out, &["--int64", "long"]);
    assert_eq!(unparsable.status.code(), Some(2), "{unparsable:?}");
}

#[test]
fn gen_warns_about_stale_files_and_deletes_nothing() {
    let (out, files) = written("gen-stale");
    let notes = fs::read_to_string(out.join("Notes/V1.elm")).expect("read");
    fs::create_dir_all(out.join("Old")).expect("create");
    fs::write(out.join("Old/V1.elm"), notes.replace("Notes.V1", "Old.V1")).expect("write");
    let output = Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .args(["gen", "notes.proto", "-I"])
        .arg(services_input())
        .arg("--out")
        .arg(&out)
        .output()
        .expect("run elm-connect");
    assert_eq!(output.status.code(), Some(0), "{output:?}");
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(stdout.lines().count(), files.len(), "{stdout}");
    let stderr = String::from_utf8_lossy(&output.stderr);
    let old = out.join("Old/V1.elm");
    assert!(
        stderr.contains(&format!(
            "warning: {} was generated by elm-connect from these protos",
            old.display()
        )),
        "{stderr}"
    );
    assert!(
        stderr.contains(&format!(
            "Wrote {} modules under {}.",
            files.len(),
            out.display()
        )),
        "{stderr}"
    );
    assert!(old.exists(), "nothing is deleted");
}

/// An edition 2023 file whose features only restate proto3 generates
/// what its proto3 twin does, so a tree generated from the one is current
/// against the other: `check` compares modules, and the edition is in the
/// protos, not in what it records.
#[test]
fn the_proto3_twin_of_a_tree_is_current() {
    let cases = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../conformance/cases");
    let generate = |case: &str| {
        elm_connect::generate(
            &[PathBuf::from("codec.proto"), PathBuf::from("other.proto")],
            &[cases.join(case).join("input")],
            false,
            &options("codec=both"),
        )
        .unwrap_or_else(|report| panic!("{report:?}"))
        .files
    };
    let out = Path::new(env!("CARGO_TARGET_TMPDIR")).join("check-twin");
    let _ = fs::remove_dir_all(&out);
    elm_connect::write(&generate("codec_both"), &out).expect("write the output");
    let check = check_tree(&generate("editions_2023_proto3_equivalent"), &out);
    assert!(check.is_current(), "{check:?}");
}
